package selprovider

import (
	"net/http"
	"testing"

	privatedns "github.com/selectel/private-dns-go/pkg/v1"
	"github.com/stretchr/testify/assert"
	"sigs.k8s.io/external-dns/endpoint"
	"sigs.k8s.io/external-dns/plan"
)

func planWithCreate(endpoints ...*endpoint.Endpoint) *plan.Changes {
	return &plan.Changes{Create: endpoints}
}

// autoRecord is generated by Private DNS for a port of a network bound to the zone.
var autoRecord = privatedns.Record{
	Type: "A", Domain: "vm-1.prod.example.com.", TTL: -1, Values: []string{"192.168.0.10"}, Generated: true,
}

func applyTestAPI(t *testing.T) *fakeAPI {
	t.Helper()

	auto := autoRecord

	return newFakeAPI(t,
		[]*privatedns.Zone{
			{ID: "prod", Domain: "prod.example.com."},
			{ID: "parent", Domain: "example.com."},
		},
		map[string][]*privatedns.Record{
			"prod": {
				&auto,
				{Type: "A", Domain: "app.prod.example.com.", TTL: -1, Values: []string{"10.0.0.1"}},
				{Type: "TXT", Domain: "a-app.prod.example.com.", TTL: -1, Values: []string{`"heritage=external-dns,external-dns/owner=prod"`}},
				{Type: "A", Domain: "old.prod.example.com.", TTL: -1, Values: []string{"10.0.0.2"}},
				{Type: "TXT", Domain: "a-old.prod.example.com.", TTL: -1, Values: []string{`"heritage=external-dns,external-dns/owner=prod"`}},
			},
		},
	)
}

func TestApplyChanges(t *testing.T) {
	t.Parallel()

	api := applyTestAPI(t)
	p := newTestProvider(t, api, Config{}, 1)

	owner := `"heritage=external-dns,external-dns/owner=prod"`
	changes := &plan.Changes{
		Create: []*endpoint.Endpoint{
			endpoint.NewEndpoint("new.prod.example.com", "A", "10.0.0.3"),
			endpoint.NewEndpoint("a-new.prod.example.com", "TXT", owner),
			endpoint.NewEndpoint("www.example.com", "CNAME", "app.prod.example.com"),
		},
		UpdateOld: []*endpoint.Endpoint{endpoint.NewEndpoint("app.prod.example.com", "A", "10.0.0.1")},
		UpdateNew: []*endpoint.Endpoint{endpoint.NewEndpointWithTTL("app.prod.example.com", "A", 60, "10.0.0.4", "10.0.0.5")},
		Delete: []*endpoint.Endpoint{
			endpoint.NewEndpoint("old.prod.example.com", "A", "10.0.0.2"),
			endpoint.NewEndpoint("a-old.prod.example.com", "TXT", owner),
			endpoint.NewEndpoint("app.example.net", "A", "10.0.0.6"),
		},
	}

	assert.NoError(t, p.ApplyChanges(t.Context(), changes))

	// One atomic request per zone; the change outside all zones is skipped.
	assert.ElementsMatch(t, []putRequest{
		{zoneID: "prod", body: privatedns.PutRecordsDTO{
			Set: []*privatedns.RecordSetDTO{
				{Type: "A", Domain: "new.prod.example.com.", Values: []string{"10.0.0.3"}},
				{Type: "TXT", Domain: "a-new.prod.example.com.", Values: []string{owner}},
				{Type: "A", Domain: "app.prod.example.com.", TTL: intPtr(60), Values: []string{"10.0.0.4", "10.0.0.5"}},
			},
			Delete: []*privatedns.RecordDeleteDTO{
				{Type: "A", Domain: "old.prod.example.com."},
				{Type: "TXT", Domain: "a-old.prod.example.com."},
			},
		}},
		{zoneID: "parent", body: privatedns.PutRecordsDTO{
			Set: []*privatedns.RecordSetDTO{
				{Type: "CNAME", Domain: "www.example.com.", Values: []string{"app.prod.example.com."}},
			},
		}},
	}, api.putRequests())

	assert.Equal(t, []privatedns.Record{
		{Type: "TXT", Domain: "a-app.prod.example.com.", TTL: -1, Values: []string{owner}},
		{Type: "TXT", Domain: "a-new.prod.example.com.", TTL: -1, Values: []string{owner}},
		{Type: "A", Domain: "app.prod.example.com.", TTL: 60, Values: []string{"10.0.0.4", "10.0.0.5"}},
		{Type: "A", Domain: "new.prod.example.com.", TTL: -1, Values: []string{"10.0.0.3"}},
		autoRecord,
	}, api.state("prod"))
	assert.Equal(t, []privatedns.Record{
		{Type: "CNAME", Domain: "www.example.com.", TTL: -1, Values: []string{"app.prod.example.com."}},
	}, api.state("parent"))
}

func TestApplyChangesLeavesAutoRecordsAlone(t *testing.T) {
	t.Parallel()

	t.Run("changes to Auto record sets are dropped from the request", func(t *testing.T) {
		t.Parallel()

		api := applyTestAPI(t)
		p := newTestProvider(t, api, Config{}, 1)

		changes := &plan.Changes{
			Create: []*endpoint.Endpoint{
				endpoint.NewEndpoint("VM-1.prod.example.com", "CNAME", "elsewhere.example.com"),
				endpoint.NewEndpoint("a-vm-1.prod.example.com", "TXT", `"heritage=external-dns"`),
			},
			UpdateOld: []*endpoint.Endpoint{endpoint.NewEndpoint("vm-1.prod.example.com", "A", "192.168.0.10")},
			UpdateNew: []*endpoint.Endpoint{endpoint.NewEndpoint("vm-1.prod.example.com", "A", "10.9.9.9")},
			Delete:    []*endpoint.Endpoint{endpoint.NewEndpoint("vm-1.prod.example.com.", "A", "192.168.0.10")},
		}

		assert.NoError(t, p.ApplyChanges(t.Context(), changes))

		assert.Equal(t, []putRequest{{zoneID: "prod", body: privatedns.PutRecordsDTO{
			Set: []*privatedns.RecordSetDTO{
				{Type: "TXT", Domain: "a-vm-1.prod.example.com.", Values: []string{`"heritage=external-dns"`}},
			},
		}}}, api.putRequests())
		assert.Contains(t, api.state("prod"), autoRecord)
	})

	t.Run("no request when every change touches Auto record sets", func(t *testing.T) {
		t.Parallel()

		api := applyTestAPI(t)
		p := newTestProvider(t, api, Config{}, 1)

		changes := &plan.Changes{
			Delete: []*endpoint.Endpoint{endpoint.NewEndpoint("vm-1.prod.example.com", "A", "192.168.0.10")},
		}

		assert.NoError(t, p.ApplyChanges(t.Context(), changes))
		assert.Empty(t, api.putRequests())
		assert.Contains(t, api.state("prod"), autoRecord)
	})
}

func TestApplyChangesDryRun(t *testing.T) {
	t.Parallel()

	api := applyTestAPI(t)
	p := newTestProvider(t, api, Config{DryRun: true}, 1)

	before := api.state("prod")
	err := p.ApplyChanges(t.Context(), planWithCreate(endpoint.NewEndpoint("new.prod.example.com", "A", "10.0.0.3")))

	assert.NoError(t, err)
	assert.Empty(t, api.putRequests())
	assert.Equal(t, before, api.state("prod"))
}

func TestApplyChangesWithoutChangesSkipsTheAPI(t *testing.T) {
	t.Parallel()

	api := applyTestAPI(t)
	p := newTestProvider(t, api, Config{}, 0)

	assert.NoError(t, p.ApplyChanges(t.Context(), &plan.Changes{}))
	assert.Empty(t, api.putRequests())
}

func TestApplyChangesErrors(t *testing.T) {
	t.Parallel()

	t.Run("API rejects the update", func(t *testing.T) {
		t.Parallel()

		api := applyTestAPI(t)
		api.putStatus = http.StatusBadRequest
		p := newTestProvider(t, api, Config{}, 1)

		err := p.ApplyChanges(t.Context(), planWithCreate(endpoint.NewEndpoint("bad.prod.example.com", "A", "x")))
		assert.ErrorContains(t, err, "update record sets of zone prod.example.com.: Record (bad.example.com. <A>) has invalid value")
	})

	t.Run("current record sets cannot be read", func(t *testing.T) {
		t.Parallel()

		api := applyTestAPI(t)
		api.recordsStatus = http.StatusNotFound
		p := newTestProvider(t, api, Config{}, 1)

		err := p.ApplyChanges(t.Context(), planWithCreate(endpoint.NewEndpoint("new.prod.example.com", "A", "10.0.0.3")))
		assert.ErrorContains(t, err, "list record sets of zone prod.example.com.")
		assert.Empty(t, api.putRequests())
	})
}
